import React from 'react';
import { IVoidDetails } from '../../../core/Interface/voidSummaryReport.interface';
import { ColumnDef } from '@tanstack/react-table';
import { useTranslation } from 'react-i18next';
import { Box } from '@mui/material';
import { formatDateTime } from '../../../core/utils';

const useVoidReportColumns = (pageIndex: number, pageSize: number) => {
  const { t } = useTranslation(['VoidDetails']);

  return [
    {
      accessorKey: 'sn',
      header: <div style={{ textAlign: 'justify' }}>#</div>,
      size: 50,
      cell: (cell) => {
        const serialNumber = pageIndex * pageSize + cell.row.index + 1;
        return <Box sx={{ textAlign: 'justify' }}>{serialNumber}</Box>;
      },
    },
    {
      accessorKey: 'productCode',
      header: t('VoidDetails:productCode'),
      size: 180,
    },
    {
      accessorKey: 'productName',
      header: t('VoidDetails:productName'),
      size: 180,
    },
    {
      accessorKey: 'quantity',
      header: () => (
        <Box sx={{ textAlign: 'center' }}>{t('VoidDetails:qty')}</Box>
      ),
      cell: (cell) => {
        return <Box sx={{ textAlign: 'center' }}>{cell.row.original.qty}</Box>;
      },
      size: 100,
    },
    {
      accessorKey: 'dateTime',
      header: () => (
        <Box sx={{ textAlign: 'right' }}>{t('VoidDetails:dateAndTime')}</Box>
      ),
      cell: (cell) => (
        <Box
          sx={{
            textAlign: 'right',
          }}
        >
          {formatDateTime(new Date(cell.row.original.createdDate))}
        </Box>
      ),
      size: 160,
    },
    {
      accessorKey: 'previousInvoiceNumber',
      header: () => (
        <Box sx={{ textAlign: 'right' }}>
          {t('VoidDetails:previousInvoiceNumber')}
        </Box>
      ),
      cell: (cell) => (
        <Box
          sx={{
            textAlign: 'right',
          }}
        >
          {cell.row.original.previousInvoiceNumber}
        </Box>
      ),
      size: 120,
    },
    {
      accessorKey: 'id',
    },
  ] as ColumnDef<IVoidDetails>[];
};

export default useVoidReportColumns;
